class UpdateError(RuntimeError):
    pass

def sha256_file(path: Path) -> str:
    h=hashlib.sha256()
    with path.open('rb') as f:
        for b in iter(lambda:f.read(1024*1024),b''): h.update(b)
    return h.hexdigest()

def read_tsv(path: Path):
    with path.open(encoding='utf-8',newline='') as f:
        r=csv.DictReader(f,delimiter='\t'); return list(r.fieldnames or []),list(r)

def read_metrics(path: Path):
    h,rows=read_tsv(path)
    if h!=['metric','value']: raise UpdateError(f'expected metric/value TSV: {path}')
    return {r['metric']:r['value'] for r in rows}

def active_canonical(path: Path) -> tuple[int,str]:
    h,rows=read_tsv(path)
    need={'stage_key','script_path','script_sha256'}
    if not need.issubset(h): raise UpdateError(f'bad current_pipeline schema: {h}')
    d=hashlib.sha256()
    for r in rows:
        if r['stage_key'].upper().startswith('15A'): raise UpdateError('Stage15A entered current_pipeline')
        p=Path(r['script_path'])
        if not p.is_file() or sha256_file(p)!=r['script_sha256']: raise UpdateError(f'active script mismatch: {p}')
        d.update((r['stage_key']+'\t'+r['script_path']+'\t'+r['script_sha256']+'\n').encode())
    return len(rows),d.hexdigest()

def run_cmd(cmd,log:Path):
    p=subprocess.run([str(x) for x in cmd],text=True,capture_output=True)
    log.parent.mkdir(parents=True,exist_ok=True); log.write_text(p.stdout+p.stderr,encoding='utf-8')
    if p.returncode: raise UpdateError(f'command failed ({p.returncode}): {cmd}; see {log}')

def validate_preflight():
    if PROJECT_ROOT!=Path('/mnt/intelssd/rnatr_project'): raise UpdateError('unexpected project root')
    for p in [SSOT_CLI,SSOT_DB,CORE_SCHEMA,CURRENT_GATES,SSOT_EXPORTS/'current_pipeline.tsv']:
        if not p.is_file(): raise UpdateError(f'missing: {p}')
    if sha256_file(SSOT_CLI)!=EXPECTED_CLI_SHA: raise UpdateError('unexpected SSOT source SHA')
    if sha256_file(SSOT_DB)!=EXPECTED_DB_SHA: raise UpdateError('unexpected SSOT DB SHA')
    if sha256_file(CORE_SCHEMA)!=EXPECTED_CORE_SCHEMA_SHA: raise UpdateError('core schema drift')
    if sha256_file(CURRENT_GATES)!=EXPECTED_GATES_V023_SHA: raise UpdateError('release gates v0.2.3 drift')
    for p,s in EXPECTED_FILES.items():
        if not p.is_file() or sha256_file(p)!=s: raise UpdateError(f'evidence missing/SHA mismatch: {p}')
    n,d=active_canonical(SSOT_EXPORTS/'current_pipeline.tsv')
    if n!=11 or d!=EXPECTED_ACTIVE_CANONICAL_SHA: raise UpdateError(f'active pipeline mismatch: {n} {d}')
    q=read_metrics(AUDIT_ROOT/'architecture_consistency_audit.qc.tsv')
    for k,v in {'architecture_audit_status':'REVIEW','blocking_conflicts':'0','replacement_checkpoint_logical_reproducibility':'true','original_checkpoint_reproducibility_claim_supported':'false','full_5_31m_run_started':'false'}.items():
        if q.get(k)!=v: raise UpdateError(f'audit QC mismatch {k}')
    run_cmd([sys.executable,SSOT_CLI,'--project-root',PROJECT_ROOT,'validate'],UPDATE_QC_ROOT/'logs/ssot_validate_before.log')
    con=sqlite3.connect(SSOT_DB)
    try:
        if con.execute('PRAGMA integrity_check').fetchone()[0]!='ok': raise UpdateError('SQLite integrity failure')
        if list(con.execute('PRAGMA foreign_key_check')): raise UpdateError('foreign-key failure')
    finally: con.close()

def backup_state():
    global BACKUP,PREEXISTING
    stamp=subprocess.check_output(['date','-u','+%Y%m%dT%H%M%SZ'],text=True).strip()
    BACKUP=SSOT_ROOT/'backups'/f'pre_stage15a_250k_archaudit_v0.1.1_{stamp}'
    BACKUP.mkdir(parents=True,exist_ok=False)
    for p,name in [(SSOT_CLI,'rnatr_ssot.py'),(SSOT_DB,'rnatr_ssot.sqlite')]: shutil.copy2(p,BACKUP/name)
    if SSOT_SUMMARY.exists(): shutil.copy2(SSOT_SUMMARY,BACKUP/'CURRENT_STATE.md')
    if SSOT_EXPORTS.exists(): shutil.copytree(SSOT_EXPORTS,BACKUP/'exports')
    for p,key in [(NEW_GATES,'gates'),(ARCH_CONTRACT,'contract'),(SELF_INSTALL,'self')]:
        PREEXISTING[key]=p.exists()
        if p.exists(): shutil.copy2(p,BACKUP/p.name)

def restore_state():
    if not BACKUP: return
    shutil.copy2(BACKUP/'rnatr_ssot.py',SSOT_CLI); shutil.copy2(BACKUP/'rnatr_ssot.sqlite',SSOT_DB)
    if (BACKUP/'CURRENT_STATE.md').exists(): shutil.copy2(BACKUP/'CURRENT_STATE.md',SSOT_SUMMARY)
    elif SSOT_SUMMARY.exists(): SSOT_SUMMARY.unlink()
    if SSOT_EXPORTS.exists(): shutil.rmtree(SSOT_EXPORTS)
    if (BACKUP/'exports').exists(): shutil.copytree(BACKUP/'exports',SSOT_EXPORTS)
    for p,key in [(NEW_GATES,'gates'),(ARCH_CONTRACT,'contract'),(SELF_INSTALL,'self')]:
        b=BACKUP/p.name
        if PREEXISTING.get(key) and b.exists(): shutil.copy2(b,p)
        elif p.exists(): p.unlink()

def install_and_patch():
    global MUTATION_STARTED
    MUTATION_STARTED=True
    ARCH_CONTRACT.parent.mkdir(parents=True,exist_ok=True); NEW_GATES.parent.mkdir(parents=True,exist_ok=True); SELF_INSTALL.parent.mkdir(parents=True,exist_ok=True)
    ARCH_CONTRACT.write_text(ARCH_CONTRACT_TEXT,encoding='utf-8')
    NEW_GATES.write_text(GATES_V024_TEXT,encoding='utf-8')
    shutil.copy2(Path(__file__).resolve(),SELF_INSTALL)
    if sha256_file(ARCH_CONTRACT)!=EXPECTED_ARCH_CONTRACT_SHA: raise UpdateError('installed architecture contract SHA mismatch')
    if sha256_file(NEW_GATES)!=EXPECTED_NEW_GATES_SHA: raise UpdateError('installed release gates SHA mismatch')
    text=SSOT_CLI.read_text(encoding='utf-8')
    if PATCH_MARKER in text: raise UpdateError('SSOT source already contains this registration marker')
    anchor='\n\n    current_metrics = ['
    if text.count(anchor)!=1: raise UpdateError(f'SSOT patch anchor count: {text.count(anchor)}')
    patched=text.replace(anchor,'\n\n'+SOURCE_INSERTION+anchor,1)
    compile(patched,str(SSOT_CLI),'exec')
    tmp=SSOT_CLI.with_name('.rnatr_ssot.py.stage15a250k.part'); tmp.write_text(patched,encoding='utf-8'); os.replace(tmp,SSOT_CLI)

def postcheck(before_pipeline_sha:str,before_schema_sha:str):
    run_cmd([sys.executable,SSOT_CLI,'--project-root',PROJECT_ROOT,'rebuild'],UPDATE_QC_ROOT/'logs/ssot_rebuild.log')
    run_cmd([sys.executable,SSOT_CLI,'--project-root',PROJECT_ROOT,'validate'],UPDATE_QC_ROOT/'logs/ssot_validate_after.log')
    if sha256_file(CORE_SCHEMA)!=before_schema_sha: raise UpdateError('core schema changed')
    after_pipeline_sha=sha256_file(SSOT_EXPORTS/'current_pipeline.tsv')
    if after_pipeline_sha!=before_pipeline_sha: raise UpdateError('current_pipeline export changed')
    n,d=active_canonical(SSOT_EXPORTS/'current_pipeline.tsv')
    if n!=11 or d!=EXPECTED_ACTIVE_CANONICAL_SHA: raise UpdateError('active pipeline changed after update')
    con=sqlite3.connect(SSOT_DB); con.row_factory=sqlite3.Row
    try:
        if con.execute('PRAGMA integrity_check').fetchone()[0]!='ok': raise UpdateError('post-update integrity failure')
        if list(con.execute('PRAGMA foreign_key_check')): raise UpdateError('post-update foreign-key failure')
        checks={
          'run':con.execute('select count(*) from runs where run_id=?',(RUN_ID,)).fetchone()[0],
          'stage':con.execute("select count(*) from stage_definitions where stage_key='15A_DETERMINISTIC_SCALING'").fetchone()[0],
          'audit_stage':con.execute("select count(*) from stage_definitions where stage_key='ARCHITECTURE_CONSISTENCY_AUDIT'").fetchone()[0],
          'impl':con.execute("select count(*) from implementations where implementation_id='impl_stage15a_scaling_250k_v0_1_2' and lifecycle_status='PROVISIONAL'").fetchone()[0],
          'audit_impl':con.execute("select count(*) from implementations where implementation_id='impl_stage15a_archaudit_post250k_v0_1_1' and lifecycle_status='REFERENCE_AUDIT'").fetchone()[0],
          'contract':con.execute("select count(*) from algorithm_contracts where component_key='architecture_consistency_audit_v0_1_0' and status='ACTIVE'").fetchone()[0],
          'question':con.execute("select count(*) from open_questions where question_key='ARCHITECTURE_CONSISTENCY_AUDIT_CLOSURE' and status='OPEN' and blocking=1").fetchone()[0],
          'failures':con.execute("select count(*) from failures where failure_id like 'stage15a_250k_%' and status='RESOLVED'").fetchone()[0],
          'pipeline15a':con.execute("select count(*) from current_pipeline where stage_key like '15A%'").fetchone()[0],
          'warnings':con.execute('select count(*) from scan_warnings').fetchone()[0],
        }
        if any(checks[k]!=1 for k in ['run','stage','audit_stage','impl','audit_impl','contract','question']): raise UpdateError(f'SSOT registration postcheck failed: {checks}')
        if checks['failures']<3 or checks['pipeline15a']!=0 or checks['warnings']!=0: raise UpdateError(f'SSOT state postcheck failed: {checks}')
    finally: con.close()
    h,rows=read_tsv(NEW_GATES); by={r['gate_id']:r for r in rows}
    if by.get('G06',{}).get('status')!='OPEN' or by.get('G07',{}).get('status')!='OPEN' or by.get('G24',{}).get('status')!='OPEN': raise UpdateError('release gates v0.2.4 status mismatch')
    return after_pipeline_sha,checks

def write_qc(before_cli,before_db,before_pipeline,after_pipeline,checks):
    UPDATE_QC_ROOT.mkdir(parents=True,exist_ok=True); UPDATE_META_ROOT.mkdir(parents=True,exist_ok=True)
    rows=[('update_version',VERSION),('run_id',RUN_ID),('ssot_cli_sha256_before',before_cli),('ssot_cli_sha256_after',sha256_file(SSOT_CLI)),('ssot_db_sha256_before',before_db),('ssot_db_sha256_after',sha256_file(SSOT_DB)),('active_pipeline_before_sha256',before_pipeline),('active_pipeline_after_sha256',after_pipeline),('active_pipeline_byte_identical',str(before_pipeline==after_pipeline).lower()),('active_pipeline_modified','false'),('core_schema_modified','false'),('deterministic_250k_scaling_registered','true'),('checkpoint_original_claim_supported','false'),('checkpoint_replacement_logical_reproducibility','true'),('architecture_audit_status','REVIEW'),('architecture_audit_blocking_conflicts','0'),('release_gates_version','v0.2.4'),('release_gate_G06','OPEN'),('release_gate_G07','OPEN'),('release_gate_G24','OPEN'),('full_5_31m_run_started','false'),('biology_layer_started','false'),('audit_status','PASS'),('next_gate','BUILD_DETERMINISTIC_500K_SCALING_WITH_CORRECTED_CHECKPOINT_AND_RUN_ID_CONTRACT')]
    p=UPDATE_QC_ROOT/'stage15a_250k_archaudit_ssot_update.qc.tsv'
    with p.open('w',encoding='utf-8',newline='') as f:
        w=csv.writer(f,delimiter='\t',lineterminator='\n'); w.writerow(['metric','value']); w.writerows(rows)
    (UPDATE_META_ROOT/'registration_contract.json').write_text(json.dumps({'version':VERSION,'run_id':RUN_ID,'checks':checks,'backup':str(BACKUP)},indent=2,sort_keys=True)+'\n',encoding='utf-8')
    return p

