    DOWNLOADS.mkdir(parents=True,exist_ok=True); UPDATE_QC_ROOT.mkdir(parents=True,exist_ok=False)
    lockfh=LOCK.open('w'); fcntl.flock(lockfh,fcntl.LOCK_EX|fcntl.LOCK_NB)
